%[text] # Denoising Workflow
%%
%[text] ## Add Files
addpath 'GT Folder'
addpath 'Real Noisy Images Folder'
addpath 'Common Functions'
addpath 'Models'
%%
%[text] ## Load Image
Image_name = 'childGT.jpeg';


GT_substring = contains(Image_name, 'GT');
% Initialization
d = 8; % depth of the n/w
imsize = -1;

if GT_substring %[output:group:1b36308a]
    % Get the ground truth image
    I = imread(fullfile('GT Folder', Image_name));
    img = imresize(I, [256 256]);
    % Add noise to the image
    noisyImg = imnoise(img, 'gaussian', 0, 0.01); % Add Gaussian noise to the image
    % Display the original and noisy images for comparison
    figure; %[output:5b6a8c06]
    subplot(1, 2, 1), imshow(img), title('Original Image'); %[output:5b6a8c06]
    subplot(1, 2, 2), imshow(noisyImg), title('Noisy Image'); %[output:5b6a8c06]

elseif ~GT_substring
    % Load noisy image
    I = imread(fullfile('Real Noisy Images Folder', Image_name));
    noisyImg = imresize(I, [256 256]);
    % Display the loaded noisy image
    figure;
    imshow(noisyImg), title('Loaded Noisy Image');
else
    assert(false, 'File Path or File name invalid')
end %[output:group:1b36308a]
%%
%[text] ## Define CNN and Noise Tensor
% --- Create Noise Tensor ---
rng(42); % Seed
input_depth = 32;
method = 'noise'; 
spatial_size = size(noisyImg, 1);
net_input = get_noise(input_depth, method, spatial_size);

%Visualize Noise
imagesc(net_input(:,:,2)) %[output:7c9f16a0]
axis image %[output:7c9f16a0]
colormap gray %[output:7c9f16a0]
colorbar %[output:7c9f16a0]

% --- Create CNN ---
num_layers = d;
num_channels = 64;
num_classes = 3;
kernel_size = 3;
[a, b, ~] = size(noisyImg);
imgSize = [a, b, input_depth]; % Set the image size for the CNN

net = DipUnet3(imgSize, num_classes);
%net = InpaintUnet3(imgSize, num_classes);

% Count parameters
totalParams = 0;
lrnables = net.Learnables;
for i = 1:height(lrnables)
    param = lrnables.Value{i};
    totalParams = totalParams + numel(extractdata(param));
end
fprintf('Number of params: %d\n', totalParams); %[output:52701fbe]
%%
%[text] ## Gradient Function
function [loss, gradients, out, out_avg, state] = modelGradients(net, net_input_saved, img_noisy, out_avg, exp_weight, reg_noise_std)

        img_noisy = dlarray(img_noisy,'SSCB');
        
        if reg_noise_std > 0
            noise = randn(size(net_input_saved), 'like', extractdata(net_input_saved));
            noise = dlarray(noise, 'SSCB'); 
            net_input = net_input_saved + noise*reg_noise_std;
        else
            net_input = net_input_saved;
        end
        
        % Forward pass
        [out, state] = forward(net, net_input);
        
        % Loss (MSE)
        loss = mean((out - img_noisy).^2,'all');
        
        
        % Output smoothing (detach)
        out_detached = dlarray(extractdata(out),'SSCB');
        
        if isempty(out_avg)
            out_avg = out_detached;
        else
            out_avg = out_avg*exp_weight + out_detached*(1-exp_weight);
        end
        
        % Gradients
        gradients = dlgradient(loss, net.Learnables);

end
%%
%[text] ## Optimization of Network
trailingAvg   = [];
trailingAvgSq = [];
reg_noise_std = 1/30;

if GT_substring
    img_gt = img;
    img_gt = im2double(img_gt);
end

PLOT = 1; % 1 for plotting and 0 otherwise
LR = 0.01;
show_every = 15;
exp_weight = 0.99;
num_iter = 10000;
out_avg = [];
last_net = [];
last_learnables = [];
psrn_noisy_last = 0;
psnr_noisy_last = -inf;
psnr_best = -inf;
best = []; % Checkpoint struct
drop_iter = 200;

beta = 0.9;
min_delta = 0.01;
iter_const = 200; % If best psnr doesn't improve after this number of iterations lr is decreased. In denoising...
% since psnr is calculated on the noisy image, psnr is not a reliable metric to ascertain the quality of denoising. 
% As a matter of fact we should expect that if our image is being denoised the
% psnr should grow and eventually plateau, increasing only slightly to fit fine edges and textures. Hence iter_const has to be high
% so as to prevent the lr being decreased unnecessarily when the best psnr
% doesn't improve which is expected behavior. 
cooldown = 30;
drop_thresh  = 1.0;
lr_decay = 0.5;
LR_min = 1e-4;
max_restores = 5;

psnr_s = [];  cooldown_left = 0;  n_restores = 0;  psnr_best_const = 0;

% --- Initialize Training Progress Monitor ---
monitor = trainingProgressMonitor( ...
    Metrics=["Loss", "PSNR", "Smoothed_PSNR"], ...
    Info=["Iteration", "LearningRate", "Best_Smoothed_PSNR"], ...
    XLabel="Iteration");

noisyImg_nom = im2double(noisyImg);

% Convert net_input to dlarray format
% --- GPU setup (only if a usable GPU exists) ---
useGPU = canUseGPU;   
if useGPU %[output:group:2b49afe5]
    fprintf('Using GPU: %s\n', gpuDevice().Name);
    gpurng(42);
    img_in = single(noisyImg_nom);      % data passed to modelGradients
else
    fprintf('No GPU available, running on CPU.\n'); %[output:632e9a33]
    img_in = noisyImg_nom;
end %[output:group:2b49afe5]

net_input_saved = single(net_input);


if useGPU
    net_input_saved = gpuArray(net_input_saved);
    img_in = gpuArray(img_in);
    net = dlupdate(@gpuArray, net);          % move learnables to the GPU
    if ~isempty(net.State)                   % move batch-norm state too
        net.State.Value = cellfun(@gpuArray, net.State.Value, 'UniformOutput', false);
    end
end

net_input_saved = dlarray(net_input_saved, 'SSCB');


% --- Training Loop ---
for iter = 1:num_iter %[output:group:6066d82f]
    
    accGradients = dlaccelerate(@modelGradients);
    [loss, gradients, out, out_avg, state] = dlfeval(accGradients,...
        net, net_input_saved, img_in, out_avg, exp_weight, reg_noise_std);

    [net, trailingAvg, trailingAvgSq] = adamupdate(net, gradients, ...
        trailingAvg, trailingAvgSq, iter, LR);
    
    % Update Batch Norm state
    net.State = state;

    % --- Convert dlarray to numeric ---
    out_num  = double(gather(extractdata(out)));
    out_num  = out_num(:,:,:,1);
    out_avg_num = double(gather(extractdata(out_avg)));
    out_avg_num = out_avg_num(:,:,:,1);
    
    noisyImg_num = im2double(noisyImg);
    % Calculate PSNR
    psnr_noisy = psnr(out_num, noisyImg_num);

    %--- Checkpointing/BackTracking ---
    if isempty(psnr_s)
        psnr_s = psnr_noisy;
    else
        psnr_s = beta*psnr_s + (1-beta)*psnr_noisy;
    end

    if psnr_noisy > psnr_best + min_delta
        psnr_best = psnr_s;
        psnr_best_const = 0;
        best.learnables = net.Learnables.Value;
        best.trailingAvg = trailingAvg;
        best.trailingAvgSq = trailingAvgSq;
        best.out_avg = out_avg;
        best.iter = iter;
        best.State = net.State;
    elseif cooldown_left > 0
        cooldown_left = cooldown_left-1;
    else
        psnr_best_const = psnr_best_const + 1;
    end

    if iter >= drop_iter && psnr_best_const >= iter_const
        if (psnr_best - psnr_s) > drop_thresh
            if n_restores < max_restores
                n_restores = n_restores + 1;
                fprintf('\nIter %d: degraded %.2f dB — restoring iter %d.\n', ...
                    iter, psnr_best - psnr_s, best.iter);
                net.Learnables.Value = best.learnables;
                trailingAvg = best.trailingAvg;
                net.State = best.State;
                trailingAvgSq = best.trailingAvgSq;
                out_avg = best.out_avg;
                psnr_s = psnr_best;
           else
            fprintf('\nIter %d: restore budget used up, continuing without restore.\n', iter);
           end
        

      else
        fprintf('\nIter %d: plateau, decaying LR only.\n', iter);
    end
    LR = max(LR * lr_decay, LR_min);
    psnr_best_const = 0;
    cooldown_left = cooldown;
    continue;
    end

    % --- Update UI Monitor ---
    recordMetrics(monitor, iter, Loss=gather(extractdata(loss)), PSNR=psnr_noisy, Smoothed_PSNR=psnr_s);
    updateInfo(monitor, ...
        "Iteration", iter + " / " + num_iter, ...
        "LearningRate", LR, ...
        "Best_Smoothed_PSNR", psnr_best);

    % Check if Stop button was pressed
    if monitor.Stop
        fprintf('\nTraining stopped by user at iteration %d.\n', iter);
        break;
    end

 

    %fprintf('Iter %05d Loss %.6f PSNR_LR: %.4f | smoothed: %.4f | best(smoothed): %.4f\r', ...
        %iter, gather(extractdata(loss)), psnr_noisy, psnr_s, psnr_best);

    if GT_substring
        img_numGT = im2double(img_gt);
        psnr_gt = psnr(out_num, img_numGT);
        psnr_gt_sm = psnr(out_avg_num, img_numGT);
        % --- Print Loss and PSNR ---
        fprintf('Iteration %05d Loss %.6f PSNR_noisy: %.4f | PSNR_Smoothed: %.4f | PSNR_gt_sm: %.4f | best(smoothed): %.4f\r', iter,gather(extractdata(loss)),... %[output:1ccc061b]
            psnr_noisy, psnr_s, psnr_gt_sm, psnr_best); %[output:1ccc061b]
    else
        % --- Print Loss and PSNR ---
        fprintf('Iteration %05d Loss %.6f PSNR_noisy: %.4f | PSNR_Smoothed: %.4f | best(smoothed): %.4f\r', iter,gather(extractdata(loss)),...
            psnr_noisy, psnr_s, psnr_best);
    end

    %--- Start Plotting ---
    if PLOT && mod(iter, show_every) == 0
        % Clip to [0, 1]
        out_plt = min(max(out_num, 0), 1);
        out_avg_plt = min(max(out_avg_num, 0), 1);
        % Plot side by side
        fig = figure(1); clf
        set(fig, 'Visible', 'on');
        subplot(1,2,1);
        imagesc(out_plt); colormap gray; axis image off;
        if GT_substring
            title(sprintf('Output (Iter %d; PSNR GT %d)', iter,psnr_gt));
        else
            title(sprintf('Output (Iter %d; PSNR Noisy %d)', iter,psnr_noisy));
        end

        subplot(1,2,2);
        imagesc(out_avg_plt); colormap gray; axis image off;
        title('Smoothed output')
        drawnow 
    end
end %[output:group:6066d82f]


% --- Restore best checkpoint before final inference ---
if ~isempty(best)
    net.Learnables.Value = best.learnables;
    out_avg = best.out_avg;
    net.State = best.State;
    fprintf('Using best checkpoint from iter %d (PSNR_LR %.4f)\n', best.iter, psnr_best);
end

%--- Save on CPU if processed on GPU ---
if useGPU
    net = dlupdate(@gather, net);
end
%%
%[text] ## Save Network
% --- Save the Model and Artifacts ---
%save('Denoising_ModelWeights.mat', 'net', 'net_input_saved', 'out_avg');
%fprintf('Model and noise tensor saved to Denoising_ModelWeights.mat\n');
%%
%[text] ## See Results
% 1. Load the saved model data
data = load('Denoising_model.mat');

% 2. Generate the raw prediction from the network
pred_raw = predict(data.net, data.net_input_saved);

% 3. Extract the numeric data from the dlarray and bring it to the CPU
img_raw = gather(extractdata(pred_raw));
img_avg = gather(extractdata(data.out_avg));

% 4. Format the arrays for image display
% Neural network outputs are often 4D (Height x Width x Channels x Batch).
% 'squeeze' removes any dimensions of size 1 (like the Batch dimension) to make it a standard 3D image.
img_raw = squeeze(img_raw);
img_avg = squeeze(img_avg);

% 5. Ensure the pixel values are in the standard [0, 1] range for imshow
img_raw = max(min(img_raw, 1), 0);
img_avg = max(min(img_avg, 1), 0);

% 6. Display the images side-by-side
figure('Name', 'Inpainting Results', 'Position', [100, 100, 900, 450]); %[output:1cc4aeb3]

subplot(1, 2, 1); %[output:1cc4aeb3]
imshow(img_raw); %[output:1cc4aeb3]
title('Raw Network Prediction'); %[output:1cc4aeb3]

subplot(1, 2, 2); %[output:1cc4aeb3]
imshow(img_avg); %[output:1cc4aeb3]
title('Averaged Output (out\_avg)'); %[output:1cc4aeb3]

